1	//! Runtime self-pricing for the hedge ladder (`PEGAINFER_SPEC_HEDGE_AUTO`).
2	//!
3	//! Instead of a hand-picked chain count, the lane measures its own operating
4	//! point: a windowed explore-then-commit controller cycles the chain count
5	//! `C ∈ {0..=Cmax}` (prefixes of `PEGAINFER_SPEC_HEDGE_POSITIONS`), scores
6	//! each window by delivered **committed tokens per second** — the objective
7	//! itself, so bucket quantization, eager penalties, and host overhead are all
8	//! priced in automatically — and commits to the argmax. A commit expires after
9	//! [`COMMIT_ROUNDS`] and re-explores, so the choice follows workload drift
10	//! (hard traffic converges to the ladder, easy traffic to `C = 0`). Per
11	//! candidate the last [`MAX_WINDOWS`] windows are kept, unweighted: after a
12	//! long commit the incumbent's windows are all recent while the challengers'
13	//! are not, which biases re-exploration toward the incumbent. Round timing uses inter-round host timestamps; gaps above
14	//! [`ROUND_GAP_CUTOFF`] (prefill, admission stalls) are treated as window
15	//! boundaries and never attributed to a chain count.
16	
17	use std::time::Duration;
18	use std::time::Instant;
19	
20	/// Rounds per exploration window. Each candidate C holds the lane for this
21	/// many verify rounds before rotating; the first rounds of a fresh shape pay
22	/// graph warm-up, which the window length amortizes.
23	const WINDOW_ROUNDS: u32 = 64;
24	/// Full rotations over all candidates before committing.
25	const EXPLORE_CYCLES: u32 = 3;
26	/// Rounds to hold a committed choice before re-exploring.
27	const COMMIT_ROUNDS: u32 = 4096;
28	/// Cheaper re-exploration after the first commit (per-candidate window).
29	const REEXPLORE_WINDOW_ROUNDS: u32 = 32;
30	/// Inter-round gaps above this are scheduling boundaries, not round cost.
31	const ROUND_GAP_CUTOFF: Duration = Duration::from_millis(500);
32	
33	/// Extra throughput a larger chain count must show over the best smaller one
34	/// (median window rate) before it is preferred. Below this the controller
35	/// takes the cheaper configuration — on a flat landscape (easy traffic) the
36	/// argmax is noise, and the noise of a 64-round window runs several percent.
37	const ADD_CHAIN_MARGIN: f64 = 1.03;
38	/// Completed windows kept per candidate (older ones age out).
39	const MAX_WINDOWS: usize = 12;
40	
41	#[derive(Default, Clone)]
42	struct CandidateStats {
43	    /// Completed exploration windows, `(tokens, secs)` each. Scored by the
44	    /// MEDIAN of per-window rates — one polluted window (graph warm-up, a
45	    /// straggling request) cannot swing the commit the way pooled sums can.
46	    windows: Vec<(f64, f64)>,
47	}
48	
49	impl CandidateStats {
50	    fn median_rate(&self) -> Option<f64> {
51	        let mut rates: Vec<f64> = self
52	            .windows
53	            .iter()
54	            .filter(|(_, secs)| *secs > 0.0)
55	            .map(|(tokens, secs)| tokens / secs)
56	            .collect();
57	        if rates.is_empty() {
58	            return None;
59	        }
60	        rates.sort_by(f64::total_cmp);
61	        Some(rates[rates.len() / 2])
62	    }
63	}
64	
65	pub(super) struct AutoHedge {
66	    stats: Vec<CandidateStats>,
67	    cur_tokens: f64,
68	    cur_secs: f64,
69	    /// Executed chain count of the in-progress window. Capacity guards can
70	    /// force a round to run below the candidate; a window only scores if
71	    /// every round in it executed the same count, so those rounds are booked
72	    /// to the configuration that actually ran.
73	    window_c: usize,
74	    cur_c: usize,
75	    committed: Option<usize>,
76	    rounds_in_window: u32,
77	    window_rounds: u32,
78	    cycles_done: u32,
79	    commit_left: u32,
80	    last_tick: Option<Instant>,
81	}
82	
83	impl AutoHedge {
84	    pub(super) fn new(max_chains: usize) -> Self {
85	        Self {
86	            stats: vec![CandidateStats::default(); max_chains + 1],
87	            cur_tokens: 0.0,
88	            cur_secs: 0.0,
89	            window_c: 0,
90	            cur_c: 0,
91	            committed: None,
92	            rounds_in_window: 0,
93	            window_rounds: WINDOW_ROUNDS,
94	            cycles_done: 0,
95	            commit_left: 0,
96	            last_tick: None,
97	        }
98	    }
99	
100	    /// Chain count for the next draft round (0 = no hedging this round).
101	    pub(super) fn current_c(&self) -> usize {
102	        self.committed.unwrap_or(self.cur_c)
103	    }
104	
105	    /// Sever the timing window: the next [`Self::tick`] only re-anchors, so the
106	    /// interval it spans is never charged to a chain count. Used when a round
107	    /// is outside the hedging configuration space (a load-gated one-token
108	    /// verify round) — booking it to `C = 0` would feed gated throughput into
109	    /// the no-hedge candidate and advance the exploration and commit counters.
110	    pub(super) fn break_window(&mut self) {
111	        self.last_tick = None;
112	        self.cur_tokens = 0.0;
113	        self.cur_secs = 0.0;
114	        self.rounds_in_window = 0;
115	    }
116	
117	    /// Record one verify round's outcome. `executed_c` is the chain count
118	    /// the round actually ran — 0 when a guard disabled hedging, whatever
119	    /// [`Self::current_c`] requested.
120	    pub(super) fn tick(&mut self, executed_c: usize, committed_tokens: usize) {
121	        let now = Instant::now();
122	        let Some(prev) = self.last_tick.replace(now) else {
123	            return;
124	        };
125	        let elapsed = now - prev;
126	        if elapsed > ROUND_GAP_CUTOFF {
127	            // Documented boundary: a stall (prefill, admission) severs the
128	            // window. Continuing it would mix measurements across whatever
129	            // the traffic looked like on either side of the stall.
130	            self.cur_tokens = 0.0;
131	            self.cur_secs = 0.0;
132	            self.rounds_in_window = 0;
133	            return;
134	        }
135	        if executed_c >= self.stats.len() {
136	            return;
137	        }
138	        if self.rounds_in_window == 0 {
139	            self.window_c = executed_c;
140	        } else if executed_c != self.window_c {
141	            self.cur_tokens = 0.0;
142	            self.cur_secs = 0.0;
143	            self.rounds_in_window = 0;
144	            self.window_c = executed_c;
145	        }
146	        self.cur_tokens += committed_tokens as f64;
147	        self.cur_secs += elapsed.as_secs_f64();
148	        self.rounds_in_window += 1;
149	        let window_done = self.rounds_in_window >= self.window_rounds;
150	        if window_done {
151	            let c = self.window_c;
152	            self.stats[c].windows.push((self.cur_tokens, self.cur_secs));
153	            if self.stats[c].windows.len() > MAX_WINDOWS {
154	                self.stats[c].windows.remove(0);
155	            }
156	            self.cur_tokens = 0.0;
157	            self.cur_secs = 0.0;
158	            self.rounds_in_window = 0;
159	        }
160	
161	        if let Some(held) = self.committed {
162	            self.commit_left = self.commit_left.saturating_sub(1);
163	            if self.commit_left == 0 {
164	                self.committed = None;
165	                self.cur_c = 0;
166	                self.cur_tokens = 0.0;
167	                self.cur_secs = 0.0;
168	                self.rounds_in_window = 0;
169	                self.cycles_done = 0;
170	                self.window_rounds = REEXPLORE_WINDOW_ROUNDS;
171	                log::info!("spec hedge auto: re-exploring (held C={held})");
172	            }
173	            return;
174	        }
175	        if !window_done {
176	            return;
177	        }
178	        if self.cur_c + 1 < self.stats.len() {
179	            self.cur_c += 1;
180	            return;
181	        }
182	        self.cur_c = 0;
183	        self.cycles_done += 1;
184	        if self.cycles_done < EXPLORE_CYCLES {
185	            return;
186	        }
187	        // Commit. Walk candidates from cheapest up; a larger chain count must
188	        // beat the running best's median window rate by ADD_CHAIN_MARGIN to
189	        // be preferred — uncertainty resolves toward fewer chains, so a flat
190	        // landscape (easy traffic) settles at the cheap end instead of the
191	        // noise argmax.
192	        let mut best = 0usize;
193	        let mut best_rate = self.stats[0].median_rate().unwrap_or(0.0);
194	        for (c, s) in self.stats.iter().enumerate().skip(1) {
195	            let Some(rate) = s.median_rate() else {
196	                continue;
197	            };
198	            if rate > best_rate * ADD_CHAIN_MARGIN {
199	                best = c;
200	                best_rate = rate;
201	            }
202	        }
203	        let rates: Vec<String> = self
204	            .stats
205	            .iter()
206	            .map(|s| {
207	                s.median_rate()
208	                    .map_or("-".to_string(), |r| format!("{r:.0}"))
209	            })
210	            .collect();
211	        log::info!(
212	            "spec hedge auto: committed C={best} (median window tok/s by C: [{}])",
213	            rates.join(", ")
214	        );
215	        self.committed = Some(best);
216	        self.commit_left = COMMIT_ROUNDS;
217	        self.cycles_done = 0;
218	    }
219	}
220	
221	#[cfg(test)]
222	mod tests {
223	    use super::*;
224	
225	    fn drive(auto: &mut AutoHedge, rounds: u32, tokens_for: impl Fn(usize) -> usize) {
226	        for _ in 0..rounds {
227	            auto.last_tick = Instant::now().checked_sub(Duration::from_millis(50));
228	            let c = auto.current_c();
229	            auto.tick(c, tokens_for(c));
230	        }
231	    }
232	
233	    #[test]
234	    fn explores_all_candidates_then_commits_to_best() {
235	        let mut auto = AutoHedge::new(3);
236	        // C=2 yields the most tokens per (constant) round time.
237	        drive(
238	            &mut auto,
239	            WINDOW_ROUNDS * 4 * EXPLORE_CYCLES + 1,
240	            |c| match c {
241	                2 => 30,
242	                3 => 28,
243	                _ => 20,
244	            },
245	        );
246	        assert_eq!(auto.committed, Some(2));
247	    }
248	
249	    #[test]
250	    fn commit_expires_into_reexploration() {
251	        let mut auto = AutoHedge::new(1);
252	        drive(&mut auto, WINDOW_ROUNDS * 2 * EXPLORE_CYCLES + 1, |c| {
253	            if c == 1 { 30 } else { 20 }
254	        });
255	        assert_eq!(auto.committed, Some(1));
256	        drive(&mut auto, COMMIT_ROUNDS, |_| 30);
257	        assert_eq!(auto.committed, None);
258	        assert_eq!(auto.window_rounds, REEXPLORE_WINDOW_ROUNDS);
259	    }
260	
261	    #[test]
262	    fn long_gaps_sever_the_window() {
263	        let mut auto = AutoHedge::new(1);
264	        // Seed a half-built window, then stall: the gap round must not be
265	        // attributed AND the pre-stall partial window must be discarded.
266	        drive(&mut auto, 10, |_| 25);
267	        assert!(auto.cur_tokens > 0.0);
268	        auto.last_tick = Instant::now().checked_sub(Duration::from_secs(2));
269	        auto.tick(0, 30);
270	        assert!(auto.cur_tokens.abs() < f64::EPSILON);
271	        assert_eq!(auto.rounds_in_window, 0);
272	    }
273	
274	    #[test]
275	    fn guard_disabled_rounds_are_booked_to_executed_config() {
276	        let mut auto = AutoHedge::new(2);
277	        // Every round runs C=0 regardless of the candidate (guard always
278	        // trips): only stats[0] may accumulate windows.
279	        drive_executed(&mut auto, WINDOW_ROUNDS * 3 * EXPLORE_CYCLES + 1, 0, 25);
280	        assert!(auto.stats[1].windows.is_empty());
281	        assert!(auto.stats[2].windows.is_empty());
282	        assert_eq!(auto.committed, Some(0));
283	    }
284	
285	    fn drive_executed(auto: &mut AutoHedge, rounds: u32, executed: usize, tokens: usize) {
286	        for _ in 0..rounds {
287	            auto.last_tick = Instant::now().checked_sub(Duration::from_millis(50));
288	            auto.tick(executed, tokens);
289	        }
290	    }
291	
292	    #[test]
293	    fn flat_landscape_settles_cheap() {
294	        let mut auto = AutoHedge::new(3);
295	        drive(&mut auto, WINDOW_ROUNDS * 4 * EXPLORE_CYCLES + 1, |_| 25);
296	        assert_eq!(auto.committed, Some(0));
297	    }
298	
299	    #[test]
300	    fn break_window_never_charges_the_gated_interval() {
301	        let mut auto = AutoHedge::new(2);
302	        drive(&mut auto, 3, |_| 10);
303	        assert!(auto.cur_tokens > 0.0 && auto.rounds_in_window > 0);
304	
305	        // A gated stretch is outside the hedging configuration space: sever the
306	        // window, and the first tick back only re-anchors.
307	        auto.break_window();
308	        assert!(auto.cur_tokens.abs() < f64::EPSILON);
309	        assert_eq!(auto.rounds_in_window, 0);
310	        auto.tick(0, 5);
311	        assert!(auto.cur_tokens.abs() < f64::EPSILON);
312	        assert_eq!(auto.rounds_in_window, 0);
313	
314	        // The next tick measures from the new anchor, not from the gated round.
315	        auto.last_tick = Instant::now().checked_sub(Duration::from_millis(10));
316	        auto.tick(0, 7);
317	        assert!((auto.cur_tokens - 7.0).abs() < f64::EPSILON);
318	        assert_eq!(auto.rounds_in_window, 1);
319	    }
320	}
