1	//! Worker-side DFlash draft lane: the draft model plus per-request draft state.
2	//!
3	//! This lives on the worker thread next to the target model because the draft
4	//! rollout reads the target's embeddings/head and its captured hidden states.
5	//! The draft/verify boundary stays a pure token span — the hidden states are
6	//! private to this lane (`pending_context`), never crossing to the scheduler.
7	
8	use std::collections::HashMap;
9	
10	use anyhow::Result;
11	use pegainfer_core::tensor::DeviceContext;
12	use pegainfer_core::tensor::HiddenStates;
13	use pegainfer_frontend::sampler::SamplingParams;
