29	pub(super) struct DFlashLaneState {
30	    pub(super) model: DFlashDraftModel,
31	    requests: HashMap<RequestId, DFlashRequestState>,
32	    /// Lane-level batched draft scratch, allocated once for the whole decode
33	    /// batch so the dense draft ops run once instead of once per request.
34	    scratch: DFlashBatchScratch,
35	    verified_draft_tokens: usize,
36	    accepted_draft_tokens: usize,
37	    /// Hedge chains proposed by the last draft round (`PEGAINFER_SPEC_HEDGE`):
38	    /// per request, one full `block_size` chain per configured branch position
39	    /// (`PEGAINFER_SPEC_HEDGE_POSITIONS`, default `0`) — chain `j` follows the
40	    /// greedy chain to `positions[j]`, takes the exact Markov runner-up there,
41	    /// and continues greedily. Consumed by the verify step's parallel hedge
42	    /// expansion; refilled every draft round.
43	    pub(super) hedge_blocks: HashMap<RequestId, Vec<Vec<u32>>>,
44	    /// Runtime chain-count controller (`PEGAINFER_SPEC_HEDGE_AUTO`); `None`
45	    /// = fixed chain count from `PEGAINFER_SPEC_HEDGE_POSITIONS`.
46	    auto: Option<super::auto_hedge::AutoHedge>,
47	    /// Chain count the LAST draft round actually ran (0 when the capacity
48	    /// guard or cap disabled hedging) — the controller books rounds to the
49	    /// executed configuration, not the requested one.
50	    round_chains: usize,
51	    /// Effective hedge geometry, resolved once against this drafter's block
52	    /// size (`spec_hedge_effective`): the clamped request cap — zero when no
53	    /// configured position can fire — and the in-block branch positions. The
54	    /// draft path, the verify dispatch, and the controller all read THESE,
55	    /// never the raw env values.
56	    hedge_cap: usize,
57	    hedge_branch_positions: Vec<usize>,
58	}
59	
60	impl DFlashLaneState {
61	    pub(super) fn new(
62	        ctx: &DeviceContext,
63	        model: DFlashDraftModel,
64	        max_decode_batch_size: usize,
65	    ) -> Result<Self> {
66	        let scratch = model.new_batch_scratch(ctx, max_decode_batch_size)?;
67	        let geometry = spec_hedge_effective(model.block_size());
68	        let hedge_branch_positions = geometry.positions;
69	        let hedge_cap = if model.uses_markov_head() && !hedge_branch_positions.is_empty() {
70	            geometry.cap
71	        } else {
72	            0
73	        };
74	        if hedge_cap > 0 {
75	            // The parser drops unparsable entries and falls back to position
76	            // 0, so a benchmark can otherwise measure a narrower ladder than
77	            // it configured.
78	            log::info!(
79	                "spec hedge on: up to {hedge_cap} request(s)/round, branch positions {:?} (block size {})",
80	                hedge_branch_positions,
81	                model.block_size()
82	            );
83	        }
84	        let auto = (spec_hedge_auto() && hedge_cap > 0).then(|| {
85	            let max_chains = hedge_branch_positions.len();
86	            log::info!("spec hedge auto: self-pricing controller on (C in 0..={max_chains})");
87	            super::auto_hedge::AutoHedge::new(max_chains)
88	        });
89	        Ok(Self {
90	            model,
91	            requests: HashMap::new(),
92	            scratch,
93	            verified_draft_tokens: 0,
94	            accepted_draft_tokens: 0,
95	            hedge_blocks: HashMap::new(),
96	            auto,
97	            round_chains: 0,
98	            hedge_cap,
99	            hedge_branch_positions,
100	        })
101	    }
102	}
103	
104	impl LocalQwen3Lane {
105	    /// Target layers whose hidden states the draft model consumes (None when
106	    /// DFlash is not loaded).
107	    pub(super) fn dflash_capture_layer_ids(&self) -> Option<Vec<usize>> {
108	        self.dflash
109	            .as_ref()
110	            .map(|dflash| dflash.model.target_layer_ids().to_vec())
111	    }
112	
113	    pub(super) fn should_capture_dflash_prefill_context(
114	        &self,
115	        requests: &[PrefillStepItem],
116	    ) -> bool {
117	        let Some(dflash) = self.dflash.as_ref() else {
118	            return false;
119	        };
120	        should_capture_dflash_prefill_context(requests, |request_id| {
121	            dflash.requests.contains_key(&request_id)
122	        })
123	    }
124	
125	    /// Fold target hidden states captured during prefill into each eligible
126	    /// request's pending context. Returns the requests that now have context.
127	    pub(super) fn record_prefill_dflash_context(
128	        &mut self,
129	        requests: &[PrefillStepItem],
130	        capture_requested: bool,
131	        captured_hidden: Option<&HiddenStates>,
132	    ) -> Result<Vec<RequestId>> {
133	        let Some(captured_hidden) = captured_hidden else {
134	            anyhow::ensure!(
135	                !capture_requested,
136	                "DFlash prefill context capture was requested but no hidden states were returned"
137	            );
138	            return Ok(Vec::new());
139	        };
140	        anyhow::ensure!(
141	            capture_requested,
142	            "DFlash prefill hidden states were returned without a capture request"
143	        );
144	        let Some(dflash) = self.dflash.as_mut() else {
145	            anyhow::bail!("DFlash prefill context record requested without DFlash");
146	        };
147	        let expected_tokens: usize = requests.iter().map(|req| req.chunk_tokens).sum();
148	        anyhow::ensure!(
149	            captured_hidden.seq_len == expected_tokens,
150	            "DFlash prefill captured {} hidden rows for {} scheduled tokens",
151	            captured_hidden.seq_len,
152	            expected_tokens
153	        );
154	        let ctx = self.model.device_ctx().clone();
155	        let mut captured_requests = Vec::new();
156	        let mut token_offset = 0usize;
157	        for req in requests {
158	            let pending_exists = dflash.requests.contains_key(&req.request_id);
159	            if dflash_prefill_can_capture(req, pending_exists) {
160	                // Admission already caps the request at `draft.max_pos - block_size`
161	                // (see `max_context_tokens`), so this `.min` is a defensive floor:
162	                // it keeps the draft KV alloc within the draft's max positions even
163	                // if a caller bypasses admission.
164	                let max_cache_len =
165	                    (req.prompt_tokens.len() + req.max_output_tokens + dflash.model.block_size())
166	                        .min(dflash.model.max_position_embeddings());
167	                let mut state = match dflash.requests.remove(&req.request_id) {
168	                    Some(state) => state,
169	                    None => dflash.model.new_request_state(&ctx, max_cache_len)?,
170	                };
171	                let pending_len = state.pending_context_len().unwrap_or(0);
172	                anyhow::ensure!(
173	                    pending_len == req.chunk_start,
174	                    "DFlash prefill context for {:?} is discontinuous: pending={}, chunk_start={}",
175	                    req.request_id,
176	                    pending_len,
177	                    req.chunk_start
178	                );
179	                dflash.model.append_pending_context(
180	                    &ctx,
181	                    &mut state,
182	                    captured_hidden,
183	                    token_offset,
184	                    req.chunk_tokens,
185	                )?;
186	                dflash.requests.insert(req.request_id, state);
187	                captured_requests.push(req.request_id);
188	            } else {
189	                dflash.requests.remove(&req.request_id);
190	            }
191	            token_offset += req.chunk_tokens;
192	        }
193	        Ok(captured_requests)
194	    }
195	
196	    /// Seed the next draft round from a verify step: append the target hidden
197	    /// states for the *accepted* span positions to each request's pending
198	    /// context, and keep the cumulative acceptance trace at debug level.
199	    pub(super) fn record_verify_dflash_context(
200	        &mut self,
201	        requests: &[VerifyStepItem],
202	        results: &[VerifyRequestResult],
203	        captured_hidden: Option<&HiddenStates>,
204	        verify_round: u64,
205	        gated: bool,
206	    ) -> Result<()> {
207	        let Some(captured_hidden) = captured_hidden else {
208	            anyhow::bail!("DFlash verify context capture requested but no hidden states returned");
209	        };
210	        let Some(dflash) = self.dflash.as_mut() else {
211	            anyhow::bail!("DFlash verify context record requested without DFlash");
212	        };
213	        anyhow::ensure!(
214	            requests.len() == results.len(),
215	            "DFlash verify result count {} does not match request count {}",
216	            results.len(),
217	            requests.len()
218	        );
219	        let expected_tokens: usize = requests.iter().map(|req| req.token_ids.len()).sum();
220	        anyhow::ensure!(
221	            captured_hidden.seq_len == expected_tokens,
222	            "DFlash verify captured {} hidden rows for {} scheduled tokens",
223	            captured_hidden.seq_len,
224	            expected_tokens
225	        );
226	        let ctx = self.model.device_ctx().clone();
227	        let mut token_offset = 0usize;
228	        for (req, result) in requests.iter().zip(results) {
229	            anyhow::ensure!(
230	                req.request_id == result.request_id,
231	                "DFlash verify result {:?} does not match request {:?}",
232	                result.request_id,
233	                req.request_id
234	            );
235	            let mut state = dflash.requests.remove(&req.request_id).ok_or_else(|| {
236	                anyhow::anyhow!("missing DFlash state after verify for {:?}", req.request_id)
237	            })?;
238	            // Only the accepted prefix's target hidden states are valid context
239	            // for the next draft; rejected drafts had the wrong continuation.
240	            dflash.model.append_pending_context(
241	                &ctx,
242	                &mut state,
243	                captured_hidden,
244	                token_offset,
245	                result.accepted_tokens.len(),
246	            )?;
247	            let context_len = state.pending_context_len().unwrap_or(0);
248	            dflash.requests.insert(req.request_id, state);
249	            dflash.verified_draft_tokens += req.token_ids.len().saturating_sub(1);
250	            dflash.accepted_draft_tokens += result.matched_draft_tokens;
251	            let rate = if dflash.verified_draft_tokens == 0 {
252	                0.0
253	            } else {
254	                dflash.accepted_draft_tokens as f64 / dflash.verified_draft_tokens as f64
255	            };
256	            let verified_draft = req.token_ids.len().saturating_sub(1);
257	            log::debug!(
258	                "Qwen3 DFlash context round={} request={} accepted_draft={} verified_draft={} gated={} committed_tokens={} context_len={} cumulative_accept_rate={:.3}",
259	                verify_round,
260	                req.request_id,
261	                result.matched_draft_tokens,
262	                verified_draft,
263	                u8::from(gated),
264	                result.accepted_tokens.len(),
265	                context_len,
266	                rate,
267	            );
268	            token_offset += req.token_ids.len();
269	        }
270	        if let Some(controller) = dflash.auto.as_mut() {
271	            let committed: usize = results
272	                .iter()
273	                .map(|result| result.accepted_tokens.len())
274	                .sum();
275	            if gated {
276	                controller.break_window();
277	            } else {
278	                controller.tick(dflash.round_chains, committed);
279	            }
280	        }
281	        Ok(())
282	    }
283	
284	    /// Roll out one draft span per request using the checkpoint's proposal head.
285	    /// Returns the verify span `[current_token, draft_1, …]`.
286	    pub(super) fn execute_dflash_draft(
287	        &mut self,
288	        requests: &[DraftStepItem],
289	    ) -> Result<DraftResult> {
290	        anyhow::ensure!(
291	            !requests.is_empty(),
292	            "DFlash draft requested without active requests"
293	        );
294	        // Take the lane out of `self` so the draft forward (which borrows
295	        // `dflash.model`/`dflash.scratch`) and the argmax (which borrows
296	        // `self.sample_scratch`) don't collide on a `self` borrow.
297	        let Some(mut dflash) = self.dflash.take() else {
298	            anyhow::bail!("DFlash draft requested but DFlash is not loaded");
299	        };
300	        let result = (|| -> Result<Vec<DraftRequestResult>> {
301	            // Pull every active request's state out of the map so the batched
302	            // forward can hold `&mut` to all of them at once. Re-inserted below.
303	            let mut taken: Vec<(RequestId, DFlashRequestState)> =
304	                Vec::with_capacity(requests.len());
305	            for req in requests {
306	                let state = dflash.requests.remove(&req.request_id).ok_or_else(|| {
307	                    anyhow::anyhow!("missing DFlash state for {:?}", req.request_id)
308	                })?;
309	                taken.push((req.request_id, state));
310	            }
311	
312	            let block_size = dflash.model.block_size();
313	            let current_tokens: Vec<u32> = requests.iter().map(|req| req.current_token).collect();
314	            let DFlashLaneState {
315	                model,
316	                scratch,
317	                requests: state_map,
318	                hedge_blocks,
319	                auto,
320	                round_chains,
321	                hedge_cap,
322	                hedge_branch_positions,
323	                ..
324	            } = &mut dflash;
325	            let mut state_refs: Vec<&mut DFlashRequestState> =
326	                taken.iter_mut().map(|(_, state)| state).collect();
327	
328	            // Backbone forward → base block logits in `scratch.logits`. Scoped so
329	            // the returned borrow of `scratch` ends before the DSpark propose path
330	            // re-borrows `scratch` mutably for its Markov sample loop.
331	            let draft_len = {
332	                let draft_logits = model.draft_logits_batched(
333	                    &self.model,
334	                    &mut state_refs,
335	                    &current_tokens,
336	                    scratch,
337	                )?;
338	                let draft_len = draft_logits.seq_len;
339	                anyhow::ensure!(
340	                    draft_len == requests.len() * block_size,
341	                    "DFlash batched draft produced {} logits rows for {} requests x block {}",
342	                    draft_len,
343	                    requests.len(),
344	                    block_size
345	                );
346	                draft_len
347	            };
348	
349	            // Plain DFlash uses independent argmax; the selector adds learned
350	            // pair scores over top-16 candidates. DSpark uses its Markov head
351	            // with an anchor-first layout (all `block_size` positions).
352	            let markov = model.uses_markov_head();
353	            let hedge_positions = if *hedge_cap > 0 {
354	                hedge_branch_positions.as_slice()
355	            } else {
356	                &[]
357	            };
358	            // Parallel hedge (PEGAINFER_SPEC_HEDGE): the chain-A loop also
359	            // captures the exact Markov runner-up at each configured branch
360	            // position, and one batched ladder pass proposes a chain per
361	            // (request, position) over the same backbone logits. Stashed
362	            // lane-side; the draft/verify token-span seam is unchanged (the
363	            // scheduler never sees hedge chains). Skipped when the ladder
364	            // would exceed the Markov scratch's max batch.
365	            hedge_blocks.clear();
366	            // Auto mode: the controller picks how many of the configured
367	            // positions to ladder this round. Always a PREFIX — runner
368	            // stripes are indexed by position order, so prefixes keep the
369	            // runner pass (always run over the full list, stable graph
370	            // shape) aligned with the ladder's stripe reads.
371	            // Batch-adaptive policy (PEGAINFER_SPEC_HEDGE_KNEE) takes precedence
372	            // over both the fixed count and the auto controller: it sets the
373	            // chain count from the free zone at THIS round's batch size, so
374	            // hedging fades to zero as concurrency fills the verify pass.
375	            let knee = spec_hedge_knee();
376	            let (ladder_chains, round_cap) = if knee > 0 {
377	                // Batch-adaptive, bucket-aware: the chain count keeps the
378	                // expanded verify batch on a CUDA-graph bucket inside the free
379	                // zone, so it fades to the baseline as concurrency rises. The
380	                // whole batch hedges at that count (the cap is not the knob).
381	                let c = batch_adaptive_chains(
382	                    requests.len(),
383	                    model.block_size(),
384	                    knee,
385	                    hedge_positions.len(),
386	                    crate::batch_decode_buffers::BATCH_BUCKETS,
387	                );
388	                log::debug!(
389	                    "spec hedge plan: batch {} -> {c} chain(s) ({} verify spans)",
390	                    requests.len(),
391	                    requests.len() * (1 + c)
392	                );
393	                (c, requests.len())
394	            } else {
395	                let c = match auto.as_ref() {
396	                    Some(controller) => controller.current_c().min(hedge_positions.len()),
397	                    None => hedge_positions.len(),
398	                };
399	                (c, *hedge_cap)
400	            };
401	            // Chains are built for the SAME requests the verify side will
402	            // hedge: eligibility travels on the draft item, and selection is
403	            // capped by the per-round request cap and the ladder's scratch
404	            // budget at the chain count that actually runs this round.
405	            let hedged = select_hedged_requests(
406	                requests,
407	                round_cap,
408	                match ladder_chains {
409	                    0 => 0,
410	                    // Slots are bounded by the ladder's Markov scratch AND by
411	                    // the verify batch's remaining span capacity — chains the
412	                    // expansion would drop at `max_batch` must not be built.
413	                    c => (scratch.markov_max_batch() / c).min(
414	                        (*crate::batch_decode_buffers::BATCH_BUCKETS.last().unwrap())
415	                            .saturating_sub(requests.len())
416	                            / c,
417	                    ),
418	                },
419	                hedge_positions.first().copied().unwrap_or(usize::MAX),
420	                model.block_size(),
421	            );
422	            let hedging = ladder_chains > 0 && !hedged.is_empty();
423	            *round_chains = if hedging { ladder_chains } else { 0 };
424	            let selector = model.uses_selector();
425	            let sampled = if selector {
426	                model.selected_draft_tokens(self.model.device_ctx(), &current_tokens, scratch)?
427	            } else if markov {
428	                if hedging {
429	                    let ctx = self.model.device_ctx();
430	                    let chain_a = model.markov_draft_with_runners(
431	                        ctx,
432	                        &current_tokens,
433	                        hedge_positions,
434	                        scratch,
435	                    )?;
436	                    let bs = model.block_size();
437	                    let req_map: Vec<u32> = hedged.iter().map(|&i| i as u32).collect();
438	                    let ladder = model.markov_chain_ladder(
439	                        ctx,
440	                        &chain_a,
441	                        &req_map,
442	                        &hedge_positions[..ladder_chains],
443	                        scratch,
444	                    )?;
445	                    let c = ladder_chains;
446	                    for (slot, &i) in hedged.iter().enumerate() {
447	                        let chains: Vec<Vec<u32>> = (0..c)
448	                            .map(|j| {
449	                                let row = slot * c + j;
450	                                ladder[row * bs..(row + 1) * bs].to_vec()
451	                            })
452	                            .collect();
453	                        hedge_blocks.insert(requests[i].request_id, chains);
454	                    }
455	                    chain_a
456	                } else {
457	                    model.markov_draft_tokens(self.model.device_ctx(), &current_tokens, scratch)?
458	                }
459	            } else {
460	                let greedy = SamplingParams::default();
461	                let params: Vec<&SamplingParams> = vec![&greedy; draft_len];
462	                self.select_step_tokens(scratch.logits(), &params, 0)?
463	            };
464	
465	            // Re-insert every request's state before splitting the result.
466	            for (request_id, state) in taken {
467	                state_map.insert(request_id, state);
468	            }
469	
470	            // Selector already drops the anchor slot. Legacy proposals still
471	            // carry full blocks, with the checkpoint-specific layout below.
472	            let sampled_stride = block_size - usize::from(selector);
473	            anyhow::ensure!(
474	                sampled.len() == requests.len() * sampled_stride,
475	                "DFlash batched draft sampled {} tokens for {} requests x stride {}",
476	                sampled.len(),
477	                requests.len(),
478	                sampled_stride
479	            );
480	
481	            // Each request owns sampled_stride entries. Selector output already
482	            // excludes its anchor; legacy anchor-drop skips position 0 here.
483	            // Anchor-first checkpoints use every sample. Prepend the actual
484	            // dangling token once for all three paths before target verification.
485	            let drafts_start = usize::from(!selector && !model.anchor_first());
486	            let keep = model.effective_drafts();
487	            let mut outputs = Vec::with_capacity(requests.len());
488	            for (i, req) in requests.iter().enumerate() {
489	                let block = &sampled[i * sampled_stride..(i + 1) * sampled_stride];
490	                let drafts = &block[drafts_start..];
491	                anyhow::ensure!(
492	                    !drafts.is_empty(),
493	                    "draft block {} produced no draft tokens (block_size {})",
494	                    i,
495	                    block_size
496	                );
497	                anyhow::ensure!(
498	                    keep <= drafts.len(),
499	                    "draft trim {} exceeds the block's {} draft tokens",
500	                    keep,
501	                    drafts.len()
502	                );
503	                let mut token_ids = Vec::with_capacity(keep + 1);
504	                token_ids.push(req.current_token);
505	                token_ids.extend(drafts[..keep].iter().copied());
506	                outputs.push(DraftRequestResult {
507	                    request_id: req.request_id,
508	                    token_ids,
509	                });
510	            }
511	            Ok(outputs)
512	        })();
513	        self.dflash = Some(dflash);
514	        Ok(DraftResult { requests: result? })
515	    }
516	
517	    pub(super) fn drop_dflash_request(&mut self, request_id: RequestId) {
518	        if let Some(dflash) = self.dflash.as_mut() {
519	            dflash.requests.remove(&request_id);
520	        }
521	    }
522	}
523	
524	/// `PEGAINFER_SPEC_HEDGE_AUTO=1` puts the hedge chain count under the
525	/// runtime self-pricing controller ([`crate::executor::auto_hedge`]): the
526	/// lane explores C ∈ {0..=len(positions)} (position-list prefixes) and
527	/// commits to the measured tokens/sec argmax. Requires the hedge to be
528	/// enabled (`PEGAINFER_SPEC_HEDGE` > 0). Read once.
529	pub(super) fn spec_hedge_auto() -> bool {
530	    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
531	    *ON.get_or_init(|| std::env::var("PEGAINFER_SPEC_HEDGE_AUTO").is_ok_and(|v| v == "1"))
532	}
533	
534	/// Effective hedge geometry for a drafter `block_size`: the clamped request
535	/// cap and the configured branch positions that can actually fire
536	/// (`p < block_size`). Startup scratch billing, verify-plan sizing, and the
537	/// draft path all budget from this ONE shape — the sites drifting apart is
538	/// how positions past the block ended up reserving pages no round could use.
539	pub(super) struct HedgeGeometry {
540	    pub(super) cap: usize,
541	    pub(super) positions: Vec<usize>,
542	}
543	
544	pub(super) fn spec_hedge_effective(block_size: usize) -> HedgeGeometry {
545	    let positions = spec_hedge_positions()
546	        .iter()
547	        .copied()
548	        .filter(|&p| p < block_size)
549	        .collect();
550	    HedgeGeometry {
551	        cap: spec_hedge_cap(),
552	        positions,
553	    }
554	}
555	
556	/// Worst-case scratch KV pages one hedge chain's verify span can touch: the
557	/// span is at most the anchor plus `block_size` drafts, at an arbitrary page
558	/// offset. Startup scratch billing and the verify-time span guard both
559	/// budget from this ONE value; the two sites carrying independent literals
560	/// is how a large-but-legal block would reserve pages the verify pass then
561	/// silently refuses to use.
562	pub(super) fn hedge_pages_per_chain(block_size: usize, page_size: usize) -> usize {
563	    // Saturating: this bills against raw config dims, where over-estimating
564	    // is safe but wrapping would under-reserve.
565	    block_size.div_ceil(page_size.max(1)).saturating_add(1)
566	}
567	
568	/// `PEGAINFER_SPEC_HEDGE=<H>` enables the parallel hedge and caps the number
569	/// of hedged requests per verify round at `H`. Each hedged request costs one
570	/// extra verify span and [`hedge_pages_per_chain`] lane scratch KV pages PER
571	/// CHAIN, so a request branching at C positions costs C of each.
572	/// `0`/unset/unparsable = off. Read once.
573	pub(super) fn spec_hedge_cap() -> usize {
574	    static CAP: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
575	    *CAP.get_or_init(|| {
576	        std::env::var("PEGAINFER_SPEC_HEDGE")
577	            .ok()
578	            .and_then(|v| v.parse::<usize>().ok())
579	            .unwrap_or(0)
580	            // Scratch pages, plan metadata, and ladder rows all scale with
581	            // the cap; clamp so a pathological value cannot blow any budget.
582	            .min(64)
583	    })
584	}
585	
586	/// `PEGAINFER_SPEC_HEDGE_KNEE=<rows>` turns on the batch-adaptive policy: the
587	/// per-round chain count is chosen so the expanded verify batch stays within
588	/// the roofline free zone of `<rows>` rows — the compute knee for this model
589	/// and GPU, below which the verify pass is weight-bandwidth-bound and extra
590	/// rows are nearly free. `0`/unset = off, keeping the fixed or auto chain
591	/// count. Read once.
592	pub(super) fn spec_hedge_knee() -> usize {
593	    static KNEE: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
594	    *KNEE.get_or_init(|| {
595	        std::env::var("PEGAINFER_SPEC_HEDGE_KNEE")
596	            .ok()
597	            .and_then(|v| v.parse::<usize>().ok())
598	            .unwrap_or(0)
599	    })
600	}
601	
602	/// Uniform hedge chain count for this batch, chosen to keep the expanded
603	/// verify batch BOTH inside the roofline free zone AND on a CUDA-graph bucket.
604	///
605	/// Every hedged request is verified over `1 + C` spans, so the batch spans
606	/// `batch * (1 + C)`. Two constraints: the rows must stay under the compute
607	/// knee (`batch * (1 + C) * span <= knee_rows`, below which extra rows are
608	/// nearly free), and the span count must be a captured graph bucket — a count
609	/// that falls between buckets runs eager and gives back the hedge gain. Return
610	/// the largest `C <= max_chains` satisfying both, or `0` when no bucket-aligned
611	/// count fits, which is how the policy fades to the baseline as concurrency
612	/// fills the zone.
613	///
614	/// A fractional free-zone remainder (a batch that fits, say, four extra chain
615	/// spans across eight requests) is deliberately NOT spent: the only span
616	/// counts between one bucket and the next are off-bucket, so partial hedging
617	/// runs eager and loses more than it gains.
618	pub(super) fn batch_adaptive_chains(
619	    batch: usize,
620	    block_size: usize,
621	    knee_rows: usize,
622	    max_chains: usize,
623	    buckets: &[usize],
624	) -> usize {
625	    if batch == 0 || knee_rows == 0 || max_chains == 0 {
626	        return 0;
627	    }
628	    let span = block_size + 1;
629	    let mut best = 0;
630	    for c in 1..=max_chains {
631	        let spans = batch * (1 + c);
632	        if spans * span > knee_rows {
633	            break; // past the free zone; larger C only goes further past
634	        }
635	        if buckets.contains(&spans) {
636	            best = c;
637	        }
638	    }
639	    best
640	}
641	
642	/// `PEGAINFER_SPEC_HEDGE_POSITIONS="0,1,2"` — draft positions at which hedge
643	/// chains branch (each takes the exact Markov runner-up at that position,
644	/// rank 2). Sorted/deduped; default `0` (the original single-chain hedge).
645	/// Read once.
646	pub(super) fn spec_hedge_positions() -> &'static [usize] {
647	    static POSITIONS: std::sync::OnceLock<Vec<usize>> = std::sync::OnceLock::new();
648	    POSITIONS.get_or_init(|| {
649	        let mut positions: Vec<usize> = std::env::var("PEGAINFER_SPEC_HEDGE_POSITIONS")
650	            .ok()
651	            .map(|v| {
652	                v.split(',')
653	                    .filter_map(|t| t.trim().parse::<usize>().ok())
654	                    .collect()
655	            })
656	            .unwrap_or_default();
657	        positions.sort_unstable();
658	        positions.dedup();
659	        positions.truncate(16);
660	        if positions.is_empty() {
661	            positions.push(0);
662	        }
663	        positions
664	    })
665	}
666	
667	impl DFlashLaneState {
668	    /// Verify-side correction for the controller's books: the round fell back
669	    /// to the plain pass (no expanded spans), so it executed as C = 0
670	    /// whatever the draft side prepared.
671	    pub(super) fn clear_round_chains(&mut self) {
672	        self.round_chains = 0;
673	    }
674	
675	    /// Effective hedged-request cap (0 = hedging cannot run on this drafter
676	    /// and the verify dispatch must not try).
677	    pub(super) fn hedge_cap(&self) -> usize {
678	        self.hedge_cap
679	    }
680	
681	    /// Number of in-block branch positions (the maximum chain count).
682	    pub(super) fn hedge_branch_count(&self) -> usize {
683	        self.hedge_branch_positions.len()
684	    }
685	}
686	
687	/// First-come selection of hedge-eligible requests under the per-round cap
688	/// and the ladder's scratch budget (both in requests). A request qualifies
689	/// only when its chains can SURVIVE the verify-side span clamp: after the
690	/// clamp it keeps `min(block_size, budget - 1)` drafts, and the earliest
691	/// branch position must land inside them — otherwise every chain collapses
692	/// onto chain A and is deduplicated away, wasting the slot. Draft and verify
693	/// pick from this same list, so neither a sampled request nor a
694	/// budget-starved greedy one ahead in the batch can burn a hedge slot the
695	/// verify side then refuses.
696	fn select_hedged_requests(
697	    requests: &[DraftStepItem],
698	    cap: usize,
699	    slots: usize,
700	    first_position: usize,
701	    block_size: usize,
702	) -> Vec<usize> {
703	    requests
704	        .iter()
705	        .enumerate()
706	        .filter(|(_, r)| r.hedge_budget >= 2 && first_position < block_size.min(r.hedge_budget - 1))
707	        .map(|(i, _)| i)
708	        .take(cap.min(slots))
709	        .collect()
710	}
711	
712	#[cfg(test)]
713	mod tests {
714	    use super::*;
715	
716	    fn item(id: u64, budget: usize) -> DraftStepItem {
717	        DraftStepItem::new(RequestId::new(id), 7, budget)
718	    }
719	
720	    const BLOCK: usize = 7;
721	
722	    #[test]
723	    fn batch_adaptive_chains_picks_the_largest_bucket_aligned_count_under_the_knee() {
724	        // block 7 -> span 8 rows; knee 96 rows = 12 spans.
725	        let bk = crate::batch_decode_buffers::BATCH_BUCKETS;
726	        let c = |b| batch_adaptive_chains(b, BLOCK, 96, 7, bk);
727	        // B=1: 1*(1+C) must be a bucket <= 12 -> {2,4,8}; largest gives C=7 (8 spans).
728	        assert_eq!(c(1), 7);
729	        // B=2: 2*(1+C) in buckets <= 12 -> {2,4,8}; 8 -> C=3, NOT the free-zone C=5.
730	        assert_eq!(c(2), 3);
731	        // B=4: 4*(1+C) in buckets <= 12 -> 8 -> C=1 (12 would be off-bucket).
732	        assert_eq!(c(4), 1);
733	        // B=8: 8*(1+C): C=0 gives 8 (baseline), C=1 gives 16 = past the knee.
734	        // 9..15 spans are all off-bucket -> no hedge fits, fade to baseline.
735	        assert_eq!(c(8), 0);
736	        assert_eq!(c(16), 0); // past the knee outright
737	        // every chosen count lands on a bucket and inside the free zone
738	        for b in 1..=32 {
739	            let cc = c(b);
740	            if cc > 0 {
741	                let spans = b * (1 + cc);
742	                assert!(
743	                    bk.contains(&spans),
744	                    "b={b} c={cc}: {spans} spans off-bucket"
745	                );
746	                assert!(spans * (BLOCK + 1) <= 96, "b={b} c={cc}: past the knee");
747	            }
748	        }
749	        // off / degenerate inputs
750	        assert_eq!(batch_adaptive_chains(1, BLOCK, 0, 7, bk), 0);
751	        assert_eq!(batch_adaptive_chains(0, BLOCK, 96, 7, bk), 0);
752	        assert_eq!(batch_adaptive_chains(1, BLOCK, 96, 0, bk), 0);
753	    }
754	
755	    #[test]
756	    fn hedge_selection_is_order_invariant_for_mixed_batches() {
757	        // H=1: the single slot must land on the greedy request in BOTH
758	        // orders — a sampled request (budget 0) must never consume it.
759	        let sampled_first = [item(1, 0), item(2, 64)];
760	        let greedy_first = [item(2, 64), item(1, 0)];
761	        assert_eq!(
762	            select_hedged_requests(&sampled_first, 1, usize::MAX, 0, BLOCK),
763	            [1]
764	        );
765	        assert_eq!(
766	            select_hedged_requests(&greedy_first, 1, usize::MAX, 0, BLOCK),
767	            [0]
768	        );
769	    }
770	
771	    #[test]
772	    fn hedge_selection_skips_spans_the_clamp_would_collapse() {
773	        // Branch position 1 with remaining budget 2: the clamp keeps one
774	        // draft, the branch cannot show, the chain would dedupe onto A. The
775	        // slot must go to the request whose span can carry the branch — in
776	        // BOTH orders.
777	        let starved_first = [item(1, 2), item(2, 64)];
778	        let healthy_first = [item(2, 64), item(1, 2)];
779	        assert_eq!(
780	            select_hedged_requests(&starved_first, 1, usize::MAX, 1, BLOCK),
781	            [1]
782	        );
783	        assert_eq!(
784	            select_hedged_requests(&healthy_first, 1, usize::MAX, 1, BLOCK),
785	            [0]
786	        );
787	        // The same budget IS enough for a position-0 branch.
788	        assert_eq!(
789	            select_hedged_requests(&starved_first, 2, usize::MAX, 0, BLOCK),
790	            [0, 1]
791	        );
792	    }
793	
794	    #[test]
795	    fn hedge_selection_respects_cap_and_slots() {
796	        let batch = [item(1, 64), item(2, 0), item(3, 64), item(4, 64)];
797	        assert_eq!(
798	            select_hedged_requests(&batch, 2, usize::MAX, 0, BLOCK),
799	            [0, 2]
800	        );
801	        assert_eq!(select_hedged_requests(&batch, usize::MAX, 1, 0, BLOCK), [0]);
802	        assert!(select_hedged_requests(&batch, 0, usize::MAX, 0, BLOCK).is_empty());
803	    }
804	}
